SourceCode.Declaration:
/// <summary>
/// The <c>AVAWHSControlQtyError</c> class is responsible for handling the error qty in report finish
/// </summary>
#AVAWHSRF
[
    WhsControlFactory(#AVAQtyError)
]
public class AVAWHSControlQtyError  extends WhsControl
{
}

Method.Source:
public boolean process()
{
    boolean     avaValid;
    Qty         avaQtyError  = WHSWorkExecuteDisplay::str2numDisplay(data);

    avaValid = super();

    if (avaQtyError <= 0)
    {
        avaValid = this.fail("@NDX:AVANoLessThanZeroErrorQty");   
        fieldValues.insert(#AVAQtyError, '');
    }
    else if (mode == WHSWorkExecuteMode::ReportAsFinished)
    {
        fieldValues.insert(#AVAQtyError, data);
    }

    return avaValid;
}
